<main class="client-hub">
 <section class="card client-hero"><div class="client-hero-top"><div><span class="client-kicker">Relaciones</span><h1>Mis clientes</h1><p>Una vista única de las personas que compraron, recibieron o usaron entradas en tus eventos.</p></div><div class="client-export"><a class="btn secondary" href="?<?php echo e(http_build_query(array_merge($_GET,array('export'=>'csv'))));?>">CSV</a><a class="btn secondary" href="?<?php echo e(http_build_query(array_merge($_GET,array('export'=>'excel'))));?>">Excel</a></div></div><div class="client-stats"><div class="client-stat"><span>Personas</span><strong><?php echo (int)$overviewTotal;?></strong></div><div class="client-stat"><span>Registrados</span><strong><?php echo (int)$overviewRegistered;?></strong></div><div class="client-stat"><span>Puerta / invitados</span><strong><?php echo (int)$overviewGuests;?></strong></div><div class="client-stat"><span>Entradas asociadas</span><strong><?php echo (int)$overviewTickets;?></strong></div></div></section>
 <section class="card client-toolbar"><form method="get"><div class="client-field search"><label for="client-q">Buscar cliente</label><input id="client-q" name="q" value="<?php echo e($q);?>" placeholder="Nombre, email, teléfono o evento"></div><div class="client-field"><label for="client-group">Tipo</label><select id="client-group" name="group"><option value="all"<?php echo $group==='all'?' selected':'';?>>Todos</option><option value="registered"<?php echo $group==='registered'?' selected':'';?>>Registrados</option><option value="guests"<?php echo $group==='guests'?' selected':'';?>>Puerta / invitados</option></select></div><div class="client-field"><label for="client-contact">Contacto</label><select id="client-contact" name="contact"><option value="all"<?php echo $contact==='all'?' selected':'';?>>Cualquiera</option><option value="email"<?php echo $contact==='email'?' selected':'';?>>Con email</option><option value="whatsapp"<?php echo $contact==='whatsapp'?' selected':'';?>>Con WhatsApp</option></select></div><div class="client-field"><label for="client-sort">Orden</label><select id="client-sort" name="sort"><option value="recent"<?php echo $sort==='recent'?' selected':'';?>>Más recientes</option><option value="az"<?php echo $sort==='az'?' selected':'';?>>Nombre A–Z</option></select></div><button class="btn" type="submit">Aplicar</button></form></section>
 <div class="client-results-head"><div><h2>Directorio</h2><p>Los eventos largos se resumen; podés ver la lista completa dejando el cursor encima.</p></div><div class="client-results-count"><?php echo (int)$totalClientes;?> resultado<?php echo $totalClientes===1?'':'s';?><?php if($q!==''||$group!=='all'||$contact!=='all'||$sort!=='recent'):?><a class="client-clear" href="mis_clientes.php">Limpiar</a><?php endif;?></div></div>
 <?php if(!$clientesList):?><section class="card client-empty"><strong>No encontramos clientes</strong><p>Probá cambiando los filtros o la búsqueda.</p></section><?php else:?><div class="client-list-head"><span>Persona</span><span>Contacto</span><span>Eventos</span><span>Entradas</span><span>Última actividad</span></div><section class="client-list">
 <?php foreach($clientesList as $client):$events=array_values($client['events']);$initial=function_exists('mb_substr')?mb_substr($client['display'],0,1,'UTF-8'):substr($client['display'],0,1);?>
  <article class="card client-row"><div class="client-person"><span class="client-avatar"><?php echo e(strtoupper($initial));?></span><div class="client-person-data"><strong title="<?php echo e($client['display']);?>"><?php echo e($client['display']);?></strong><span class="client-badge<?php echo $client['is_reg']?' registered':'';?>"><?php echo $client['is_reg']?'Registrado':'Puerta / invitado';?></span></div></div><div class="client-contact"><strong title="<?php echo e($client['email']);?>"><?php echo $client['email']!==''?e($client['email']):'Sin email';?></strong><small><?php echo $client['telefono']!==''?e($client['telefono']):'Sin WhatsApp registrado';?></small></div><div class="client-events" title="<?php echo e(implode(' · ',$events));?>"><span class="client-event-primary"><?php echo $events?e($events[0]):'Sin evento';?></span><?php if(count($events)>1):?><span class="client-event-more">+<?php echo count($events)-1;?> evento<?php echo count($events)-1===1?'':'s';?></span><?php endif;?></div><div class="client-tickets"><strong><?php echo (int)$client['tickets'];?></strong><small>Entradas</small></div><div class="client-activity"><?php echo $client['last_raw']!==''?e($client['last_raw']):(!empty($client['last_ts'])?date('d/m/Y H:i',$client['last_ts']):'Sin fecha');?><small><?php echo e(implode(' · ',$client['sources']));?></small></div></article>
 <?php endforeach;?></section><?php endif;?>
</main>
